body.raw:
{
  "query": "query SearchCards($q: String!) {
  search(
    query: $q
    first: 25
    types: PRODUCT
    productFilters: [{ available: true }, { productType: "MTG Single" }]
  ) {
    edges {
      node {
        ... on Product {
          title
          handle
          availableForSale
          productType
          tags
          featuredImage { url }
          variants(first: 20) {
            edges {
              node {
                title
                availableForSale
                price { amount }
              }
            }
          }
        }
      }
    }
  }
}",
  "variables": {
    "q": "{{search_query}}"
  }
}
